import{_ as c,C as l,o as i,c as n,aj as r,E as o,j as d,a}from"./chunks/framework.DkvuVDKz.js";const x=JSON.parse('{"title":"Scrollbar 滚动条","description":"","frontmatter":{},"headers":[],"relativePath":"components/scrollbar.md","filePath":"components/scrollbar.md","lastUpdated":1789272501000}'),h={name:"components/scrollbar.md"};function s(b,t,u,p,m,g){const e=l("XhDemo");return i(),n("div",null,[t[0]||(t[0]=r('<h1 id="scrollbar-滚动条" tabindex="-1">Scrollbar 滚动条 <a class="header-anchor" href="#scrollbar-滚动条" aria-label="Permalink to &quot;Scrollbar 滚动条&quot;">​</a></h1><p>为现有滚动容器提供一致的滚动条样式。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/scrollbar" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/scrollbar.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/scrollbar" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/scrollbar" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/scrollbar.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>为滚动容器添加滚动条</p>',5)),o(e,{src:"scrollbar/01-basic"}),t[1]||(t[1]=r('<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to &quot;组件结构&quot;">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;scrollbar&quot;</code>：<strong><code>root</code></strong> · <strong><code>track</code></strong> · <strong><code>thumb</code></strong> · <code>corner</code></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="键盘操作" tabindex="-1">键盘操作 <a class="header-anchor" href="#键盘操作" aria-label="Permalink to &quot;键盘操作&quot;">​</a></h3><p>让滑块可聚焦</p>',6)),o(e,{src:"scrollbar/02-focusable"}),t[2]||(t[2]=d("h3",{id:"双轴滚动",tabindex:"-1"},[a("双轴滚动 "),d("a",{class:"header-anchor",href:"#双轴滚动","aria-label":'Permalink to "双轴滚动"'},"​")],-1)),t[3]||(t[3]=d("p",null,"同时显示横向和纵向滚动条",-1)),o(e,{src:"scrollbar/03-both-axes"}),t[4]||(t[4]=d("h3",{id:"显示方式",tabindex:"-1"},[a("显示方式 "),d("a",{class:"header-anchor",href:"#显示方式","aria-label":'Permalink to "显示方式"'},"​")],-1)),t[5]||(t[5]=d("p",null,"设置滚动条的显示时机",-1)),o(e,{src:"scrollbar/04-types"}),t[6]||(t[6]=r('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>需要统一不同平台的滚动条样式。</li><li>需要为已有滚动容器补充自定义滚动条。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>需要完整的滚动容器时，使用<a href="./scroll-area">滚动区域</a>。</li><li>只需调整原生滚动条宽度时，优先使用 CSS。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li>支持五种显示时机，默认在滚动或悬停时显示。</li><li>支持拖动、点击轨道、键盘操作与 RTL。</li><li>支持横向、纵向和双轴滚动。</li><li>触屏设备默认保留原生滚动体验。</li></ul><h3 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h3><ul><li>可与<a href="./table">表格</a>、<a href="./virtualizer">虚拟滚动</a>和<a href="./log">日志</a>组合使用。</li><li>双轴滚动时使用 <code>gutter</code> 和 <code>corner</code> 处理交叉区域。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>保留滚动容器的原生滚轮和键盘能力。</li><li>触摸设备不要仅使用 <code>hover</code> 显示模式。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h3><ul><li>不要为每条辅助滚动条都启用 <code>focusable</code>。</li><li>不要用滚动条组件拦截滚轮事件。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to &quot;API 参考&quot;">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-scrollbar&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhScrollbarCorner</code> <code>XhScrollbarRoot</code> <code>XhScrollbarThumb</code> <code>XhScrollbarTrack</code></td></tr><tr><td>组合式函数</td><td><code>useScrollbar</code></td></tr><tr><td>状态机</td><td><code>scrollbarMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/scrollbar.css</code></td></tr></tbody></table><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>orientation</code></td><td><code>Orientation</code></td><td></td><td>这条滚动条管哪条轴，默认 vertical。</td></tr><tr><td><code>type</code></td><td><code>ScrollbarType</code></td><td></td><td>露面的时机，默认 scroll-hover。</td></tr><tr><td><code>hideDelay</code></td><td><code>number</code></td><td></td><td>收起前的等待毫秒（type 为 scroll / hover / scroll-hover 时生效），默认 600。</td></tr><tr><td><code>minThumbSize</code></td><td><code>number</code></td><td></td><td>滑块最短多少像素，默认 20。长文档里的滑块再短也按得住。</td></tr><tr><td><code>step</code></td><td><code>number</code></td><td></td><td>方向键一步滚多少像素，默认 40。翻页键按视口长度走，不看这个值。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg，换的是滚动条厚度。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td>禁用：不接指针也不接键盘，恒不显形。</td></tr><tr><td><code>focusable</code></td><td><code>boolean</code></td><td></td><td>滑块进 Tab 序并报 role=scrollbar，默认 false。 缺省不进：滚动容器自己已经能用键盘滚，再给每条滚动条一个 Tab 停靠点， 长页面上会平白多出十几站。要键盘操作滑块本身时才开。</td></tr><tr><td><code>controls</code></td><td><code>string</code></td><td></td><td>被控滚动容器的 id；focusable 时落到滑块的 aria-controls 上（没给就用容器自己的 id）。</td></tr><tr><td><code>gutter</code></td><td><code>boolean</code></td><td></td><td>横竖两条同时摆着时，各自在末端让出交叉口那一格：竖条不伸到底、横条不伸到头。 交叉口由其中一条里的 corner 部件补上。</td></tr><tr><td><code>forceVisible</code></td><td><code>boolean</code></td><td></td><td>触屏设备（粗指针）上也显形，默认 false：触屏没有悬停、拖滑块也不如直接划内容， 缺省交给原生滚动，本组件整条不显形并带 data-native。</td></tr><tr><td><code>dir</code></td><td><code>Direction</code></td><td></td><td>排版方向，默认随文档。只影响横轴：RTL 下滚动量的正负、指针位移的方向都要翻一次。 必须显式给：组件不读计算样式，看不见从 RTL 祖先继承来的方向。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;ScrollbarTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>onScrollStart</code></td><td><code>(details: ScrollbarScrollDetails) =&gt; void</code></td><td></td><td>开始滚了（停手 120ms 才算一段结束，中途连滚不重复通知）。</td></tr><tr><td><code>onScrollEnd</code></td><td><code>(details: ScrollbarScrollDetails) =&gt; void</code></td><td></td><td>一段滚动结束。</td></tr><tr><td><code>onDragStart</code></td><td><code>(details: ScrollbarScrollDetails) =&gt; void</code></td><td></td><td>按住滑块。</td></tr><tr><td><code>onDragEnd</code></td><td><code>(details: ScrollbarScrollDetails) =&gt; void</code></td><td></td><td>松开滑块。</td></tr></tbody></table><h3 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h3><p>自定义元素将载荷放在 <code>detail</code>；Vue 使用同名 emit。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>name</code></td><td><code>CustomEvent</code></td><td></td></tr><tr><td><code>scroll-start</code></td><td>``</td><td>开始滚了；detail 为 <code>{ offset: number, max: number }</code></td></tr><tr><td><code>scroll-end</code></td><td>``</td><td>一段滚动结束（停手 120ms）；detail 同上</td></tr><tr><td><code>drag-start</code></td><td>``</td><td>按住滑块；detail 同上</td></tr><tr><td><code>drag-end</code></td><td>``</td><td>松开滑块；detail 同上</td></tr></tbody></table><h3 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h3><p>仅列出带载荷的插槽。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhScrollbarRoot</code></td><td><code>default</code></td><td><code>ScrollbarRootSlotProps</code></td><td></td></tr></tbody></table><h3 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h3><p>公开状态写入 <code>data-state</code>。</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;visible&#39; | &#39;hidden&#39;</td></tr><tr><td><code>corner</code></td><td>&#39;visible&#39; | &#39;hidden&#39;</td></tr></tbody></table><p>以下名称仅用于内部状态机。</p><p><strong>状态</strong>：<code>hidden</code> · <code>visible</code> · <code>hiding</code> · <code>dragging</code></p><p><strong>事件</strong>：<code>MEASURE</code> · <code>SCROLL</code> · <code>SCROLL.IDLE</code> · <code>POINTER.ENTER</code> · <code>POINTER.LEAVE</code> · <code>DRAG.START</code> · <code>DRAG.MOVE</code> · <code>DRAG.END</code> · <code>TRACK.CLICK</code> · <code>STEP</code> · <code>SCROLL.TO</code> · <code>after.hideDelay</code></p><p><strong>判据</strong>：<code>showsOnHover</code> · <code>showsOnScroll</code> · <code>staysVisible</code> · <code>canInteract</code></p><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>orientation</code></td><td><code>Orientation</code></td><td></td></tr><tr><td><code>type</code></td><td><code>ScrollbarType</code></td><td></td></tr><tr><td><code>overflow</code></td><td><code>boolean</code></td><td>内容比可视区长。不溢出时 auto 档整条不显形。</td></tr><tr><td><code>visible</code></td><td><code>boolean</code></td><td>这一刻该不该显形（已把 type、disabled 与触屏原生那一路都算进去）。</td></tr><tr><td><code>native</code></td><td><code>boolean</code></td><td>交给了原生滚动：粗指针设备且没开 forceVisible，整条不显形。</td></tr><tr><td><code>hover</code></td><td><code>boolean</code></td><td>指针此刻在滚动容器或滚动条上。</td></tr><tr><td><code>dragging</code></td><td><code>boolean</code></td><td>手正按在滑块上。</td></tr><tr><td><code>scrolling</code></td><td><code>boolean</code></td><td>这一段滚动还在进行中。</td></tr><tr><td><code>thumbSize</code></td><td><code>number</code></td><td>滑块长度占轨道的比例，0-1。</td></tr><tr><td><code>thumbOffset</code></td><td><code>number</code></td><td>滑块起点占轨道的比例，0-1。</td></tr><tr><td><code>scroll</code></td><td><code>number</code></td><td>距逻辑起始缘的滚动量（px）。</td></tr><tr><td><code>max</code></td><td><code>number</code></td><td>还能往前滚多少（px）。</td></tr><tr><td><code>scrollTo</code></td><td><code>(offset: number) =&gt; void</code></td><td>滚到某个绝对位置（px），越界自动夹。</td></tr><tr><td><code>scrollBy</code></td><td><code>(delta: number) =&gt; void</code></td><td>相对当前位置滚若干像素。</td></tr><tr><td><code>measure</code></td><td><code>() =&gt; void</code></td><td>重新量一遍。内容长短变了会自动重量（MutationObserver 盯着容器子树）， 这个出口留给量不到的那些：容器换了、内容在 Shadow DOM 里、或是自定义元素内部改的。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTrackProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getThumbProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getCornerProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td>交叉口补丁，写在其中一条的 root 里；跟着这一条的显隐走。</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/WCAG21/Techniques/general/G202" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>ArrowUp</code> / <code>ArrowLeft</code></td><td>focus in thumb, focusable, 与本轴同向</td><td>往回滚一步（step，默认 40px）；交叉轴的那一个不拦，照常交给页面</td></tr><tr><td><code>ArrowDown</code> / <code>ArrowRight</code></td><td>focus in thumb, focusable, 与本轴同向</td><td>往前滚一步</td></tr><tr><td><code>PageUp</code></td><td>focus in thumb, focusable</td><td>往回滚一屏（按滚动容器的可视长度）</td></tr><tr><td><code>PageDown</code></td><td>focus in thumb, focusable</td><td>往前滚一屏</td></tr><tr><td><code>Home</code></td><td>focus in thumb, focusable</td><td>滚到起点</td></tr><tr><td><code>End</code></td><td>focus in thumb, focusable</td><td>滚到终点</td></tr><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>focusable</td><td>滑块是一个 Tab 停靠点；不开 focusable 时整条退出 Tab 序，也对读屏隐藏</td></tr></tbody></table><h3 id="aria" tabindex="-1">ARIA <a class="header-anchor" href="#aria" aria-label="Permalink to &quot;ARIA&quot;">​</a></h3><p>以下属性由 <code>connect</code> 生成。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-hidden</code></td><td>undefined | &#39;true&#39;</td></tr><tr><td><code>thumb</code></td><td><code>aria-controls</code></td><td>props.controls | undefined</td></tr><tr><td><code>thumb</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | undefined</td></tr><tr><td><code>thumb</code></td><td><code>aria-label</code></td><td>props.translations.thumb | undefined</td></tr><tr><td><code>thumb</code></td><td><code>aria-orientation</code></td><td>props.orientation | undefined</td></tr><tr><td><code>thumb</code></td><td><code>aria-valuemax</code></td><td>Math.round(max) | undefined</td></tr><tr><td><code>thumb</code></td><td><code>aria-valuemin</code></td><td>0 | undefined</td></tr><tr><td><code>thumb</code></td><td><code>aria-valuenow</code></td><td>Math.round(metrics.scroll) | undefined</td></tr><tr><td><code>thumb</code></td><td><code>role</code></td><td>&#39;scrollbar&#39; | undefined</td></tr></tbody></table><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to &quot;样式参考&quot;">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to &quot;皮肤&quot;">​</a></h3><p><code>@xihan-ui/styles/scrollbar.css</code> 使用 <code>[data-scope=&quot;scrollbar&quot;][data-part=&quot;root&quot;]</code> 部件选择器，位于 <code>xihan.components</code> 层。覆盖样式使用 <code>xihan.overrides</code>。</p><h3 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h3><p>由 <code>connect</code> 生成；条件不成立时不输出无值属性。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-dragging</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-gutter</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-native</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>root</code></td><td><code>data-reveal-mode</code></td><td>props.type</td></tr><tr><td><code>root</code></td><td><code>data-scrolling</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;visible&#39; | &#39;hidden&#39;</td></tr><tr><td><code>track</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>track</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>thumb</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>thumb</code></td><td><code>data-dragging</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>thumb</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>corner</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>corner</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>corner</code></td><td><code>data-state</code></td><td>&#39;visible&#39; | &#39;hidden&#39;</td></tr></tbody></table><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；缺省来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>缺省来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-scrollbar-corner-bg</code></td><td><code>corner</code></td><td><code>background</code></td><td><code>default</code></td><td><code>--xh-scrollbar-track-bg</code></td><td>scrollbar 的 corner 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-scrollbar-thumb-bg</code></td><td><code>thumb</code></td><td><code>background</code></td><td><code>default</code></td><td><code>--xh-fg-scrollbar-thumb</code></td><td>scrollbar 的 thumb 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-scrollbar-thumb-bg-active</code></td><td><code>thumb</code></td><td><code>background</code></td><td><code>dragging</code></td><td><code>--xh-fg-scrollbar-thumb-active</code></td><td>scrollbar 的 thumb 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-scrollbar-thumb-bg-disabled</code></td><td><code>thumb</code></td><td><code>background</code></td><td><code>disabled</code></td><td><code>--xh-border-subtle</code></td><td>scrollbar 的 thumb 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-scrollbar-thumb-bg-hover</code></td><td><code>thumb</code></td><td><code>background</code></td><td><code>hover</code></td><td><code>--xh-fg-scrollbar-thumb-hover</code></td><td>scrollbar 的 thumb 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-scrollbar-thumb-radius</code></td><td><code>thumb</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-pill</code></td><td>scrollbar 的 thumb 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-scrollbar-track-bg</code></td><td><code>corner</code><br><code>track</code></td><td><code>background</code></td><td><code>default</code></td><td><code>--xh-bg-scrollbar-track</code></td><td>scrollbar 的 corner、track 部件 background 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h3><p><code>background</code> · <code>color</code> · <code>opacity</code> · <code>visibility</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h3 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h3><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p>',55))])}const k=c(h,[["render",s]]);export{x as __pageData,k as default};
